def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return "", False

        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            value = f"{local}@gmail.com"

        local, domain = value.split("@")
        valid = bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")
        return value, valid

    def normalize_phone(value):
        match = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        valid = len(digits) == 10 and digits[0] not in "01"
        return (digits if valid else ""), valid

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            value = value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        first_name = normalize_name(row["first_name"])
        last_name = normalize_name(row["last_name"])
        email, email_valid = normalize_email(row["email"])
        phone, phone_valid = normalize_phone(row["phone"])
        updated = parse_updated(row["updated"])

        if not email_valid and not phone_valid:
            continue

        prepared.append({
            "index": index,
            "first_name": first_name,
            "last_name": last_name,
            "zip": normalize_zip(row["zip"]),
            "email": email if email_valid else "",
            "phone": phone if phone_valid else "",
            "source": row["source"].strip().lower(),
            "opted_out": row["opted_out"].strip().lower() in {"y", "yes", "true", "1"},
            "updated_dt": updated,
            "tags": row["tags"],
        })

    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_last_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        last_key = row["last_name"].lower()
        if row["phone"] and last_key:
            key = (row["phone"], last_key)
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def best_value(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""
        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )
        return best[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(row["index"] for row in g)):
        tags = set()
        for row in group:
            tags.update(
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            )

        latest = max(row["updated_dt"] for row in group)
        output.append({
            "first_name": best_value(group, "first_name"),
            "last_name": best_value(group, "last_name"),
            "zip": best_value(group, "zip"),
            "email": best_value(group, "email"),
            "phone": best_value(group, "phone"),
            "source": best_value(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
